// Reusable two-column PDF layout-text parser for Pathfinder Kingmaker Bestiary.
// Input: [{page: PDF_page_number, text: pdftotext_-layout_page_text}].
// REVIEW ALL AUTOGENERATED RECORDS before live combat; no copyrighted prose archived.
const titleCase=name=>name.toLowerCase().replace(/(^|[\s(\/\-])([a-z])/g,(_,a,b)=>a+b.toUpperCase());
const clean=s=>String(s||"").replace(/[−–]/g,"-").replace(/\s+/g," ").trim();
const number=s=>{const m=/[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?/.exec(clean(s));return m?Number(m[0].replaceAll(",","")):null;};
const stop=/^(?:DEFENSE|OFFENSE|STATISTICS|SPECIAL ABILITIES|TACTICS|ECOLOGY|DESCRIPTION|During Combat|Before Combat|Morale|Melee\b|Ranged\b|Space\b|Special Attacks\b|Speed\b|AC\b|hp\b|Fort\b|Init\b|Str\b|Base Atk\b|Feats\b|Skills\b|Languages\b|SQ\b|Combat Gear\b|Other Gear\b|Gear\b|Defensive Abilities\b|Weaknesses\b|Aura\b|Immune\b|DR\b|SR\b|Resist\b|Spell-Like Abilities\b|.+ Spells Prepared\b|Spells Prepared\b)/i;
function half(line){
 const src=line.slice(0,142);
 const c=[...src.matchAll(/ {3,}(\S)/g)].map(m=>m.index+m[0].length-1).filter(x=>x>=57&&x<=82);
 const cut=c.at(-1);
 if(cut!==undefined&&!/^CR\s+(?:\d+(?:\/\d+)?|—)\s*$/.test(src.slice(cut).trim()))return [src.slice(0,cut).trim(),src.slice(cut).trim()];
 if(src.search(/\S/)>=57)return ["",src.trim()];
 return [src.trim(),""];
}
function chapterText(pages){
 let all="";
 for(const p of pages){
  const left=[],right=[];
  for(const ln of p.text.split("\n")){const [a,b]=half(ln);if(a)left.push(a);if(b)right.push(b);}
  all+="\n[[PDFPAGE:"+p.page+"]]\n"+left.join("\n")+"\n"+right.join("\n");
 }
 return all;
}
function field(lines,label,cap=4){
 const find=new RegExp("^"+label+"(?:\\b|\\s|:)","i"),idx=lines.findIndex(x=>find.test(x));
 if(idx<0)return "";
 const items=[lines[idx].replace(find,"").trim()];
 for(let j=idx+1;j<Math.min(lines.length,idx+cap);j++){
  const s=lines[j].trim();
  if(!s||/^\[\[PDFPAGE:/.test(s)||stop.test(s)||/^[A-Z][A-Z0-9 '()\-]{2,}\s+CR\b/.test(s))break;
  items.push(s);
 }
 return clean(items.join(" "));
}
function skills(text){
 if(!text)return [];
 const out=[],seen=new Set();
 for(const m of text.matchAll(/(?:^|[,;])\s*([A-Za-z][A-Za-z0-9 ()'\/+\-]{1,55}?)\s+([+-]\d+)(?=\s*[,;(]|$)/g)){
  const name=clean(m[1]),bonus=number(m[2]);
  if(name&&!seen.has(name)&&bonus!==null){out.push({name,bonus});seen.add(name);}
 }
 return out.slice(0,100);
}
function attacks(text,type){
 if(!text)return [];
 const out=[];
 for(const segment of text.split(/\s+or\s+(?=[^)]*\()/i)){
  const rx=/([^,;()]{2,75}?)\s+([+-]\d+(?:\s*\/\s*[+-]\d+)*)\s*(?:touch\s*)?\(([^)]{2,110})\)/g;
  for(const m of segment.matchAll(rx)){
   const label=clean(m[1]).replace(/^(?:Melee|Ranged|or)\s+/i,"");
   const nums=m[2].split("/").map(number).filter(n=>n!==null);
   const formula=/\b\d+d\d+(?:[+-]\d+)?\b/i.exec(clean(m[3]))?.[0]||"";
   for(let i=0;i<nums.length;i++)out.push({name:(label+(nums.length>1?" attack "+(i+1):"")).slice(0,100),attack_type:type,npcAttackBonus:nums[i],damage:formula,desc:clean(m[3]).slice(0,180)});
  }
 }
 return out.slice(0,50);
}
function parseRaw(name,cr,raw,category,page){
 const lines=raw.replace(/\r/g,"").split("\n").map(x=>x.trim()).filter(x=>x&&!/^\[\[PDFPAGE:/.test(x));
 const g=(label,max=4)=>field(lines,label,max),fixed=raw.replaceAll("−","-").replaceAll("–","-");
 const stats={},txt={},flags=[];
 const put=(key,value)=>{if(Number.isFinite(value))stats[key]=value;};
 const xp=g("XP",1),hp=g("hp",2),ac=g("AC",2),init=g("Init",2),fort=g("Fort",2),base=g("Base Atk",2),speed=g("Speed",2),scores="Str "+g("Str",2); // field() strips its matching label; restore it for Strength
 const frac=/^(\d+)\/(\d+)$/.exec(cr);
 put("cr",frac?Number(frac[1])/Number(frac[2]):number(cr));
 put("xp",number(xp));put("initiative",number(init));put("ac",number(ac));
 put("touch",number(/\btouch\s+([+-]?\d+)/i.exec(ac)?.[1]));
 put("flat",number(/\bflat-footed\s+([+-]?\d+)/i.exec(ac)?.[1]));
 put("fort",number(fort));put("ref",number(/\bRef\s+([+-]?\d+)/i.exec(fort)?.[1]));put("will",number(/\bWill\s+([+-]?\d+)/i.exec(fort)?.[1]));
 put("bab",number(base));put("cmb",number(/\bCMB\s+([+-]?\d+)/i.exec(base)?.[1]));put("cmd",number(/\bCMD\s+([+-]?\d+)/i.exec(base)?.[1]));
 const h=number(hp),hd=/(\d+)\s*HD\b/.exec(hp),hitdice=hd?Number(hd[1]):[...hp.matchAll(/(\d+)d(?:4|6|8|10|12|20)\b/g)].reduce((a,m)=>a+Number(m[1]),0);
 if(hitdice)put("hitDice",hitdice);
 if(/^\d+\s*ft/.test(speed))put("speed",number(speed));
 for(const key of ["fly","swim","climb","burrow"]){const v=new RegExp("\\b"+key+"\\s+(\\d+)\\s*ft","i").exec(speed);if(v)put(key+"Speed",number(v[1]));}
 const space=g("Space",1);put("space",number(space));put("reach",number(/\bReach\s+(\d+)/i.exec(space)?.[1]||g("Reach",1)));
 put("perception",number(/\bPerception\s+([+-]\d+)/i.exec(init)?.[1]||/\bPerception\s+([+-]\d+)/i.exec(fixed)?.[1]));
 for(const key of ["Str","Dex","Con","Int","Wis","Cha"]){const m=new RegExp("\\b"+key+"\\s+([+-]?\\d+|—)\\b","i").exec(scores);if(m)put(key.toLowerCase(),number(m[1]));}
 const lineDR=g("DR",1);put("dr",number(lineDR));put("sr",number(g("SR",1)));
 const cast=/\b(?:CL|caster level)\s+(\d+)(?:st|nd|rd|th)?\b/i.exec(fixed);if(cast)put("casterLevel",number(cast[1]));
 const identityLine=lines.find(l=>/^(?:LG|NG|CG|LN|N|CN|LE|NE|CE)\s+(?:Fine|Diminutive|Tiny|Small|Medium|Large|Huge|Gargantuan|Colossal)\b/.test(l));
 if(identityLine){const m=/^(LG|NG|CG|LN|N|CN|LE|NE|CE)\s+(Fine|Diminutive|Tiny|Small|Medium|Large|Huge|Gargantuan|Colossal)\s+(.+)$/.exec(identityLine);if(m){txt.alignment=m[1];txt.size=m[2];txt.creatureType=clean(m[3]).replace(/\([^)]*\).*/,"").trim();const sub=/\(([^)]+)\)/.exec(m[3]);if(sub)txt.subtypes=sub[1];}}
 const sourceLine=lines.find(l=>/\(Pathfinder\b/.test(l));if(sourceLine)txt.sourceReference=sourceLine.slice(0,220);
 const senses=/\bSenses\s+([^;]+)/i.exec(g("Init",3));if(senses)txt.senses=clean(senses[1]).slice(0,400);
 for(const [label,key,max,cut] of [["Aura","aura",4,600],["Defensive Abilities","defenses",4,800],["Resist","energyResistances",2,350],["Immune","immunities",2,350],["Weaknesses","weaknesses",2,350],["Special Attacks","specialAttacks",6,850],["Languages","languages",4,500],["Gear","gear",5,900],["Combat Gear","combatGear",5,600],["Feats","feats",6,1300],["SQ","qualities",4,700]]){
  const val=g(label,max);if(val)txt[key]=val.slice(0,cut);
 }
 if(lineDR)txt.drBypass=lineDR.replace(/^\s*\d+\s*\/\s*/,"").slice(0,160);
 const melee=g("Melee",5),ranged=g("Ranged",5);
 if(melee||ranged)txt.attackDetail=clean([melee?"Melee "+melee:"",ranged?"Ranged "+ranged:""].filter(Boolean).join("; ")).slice(0,1200);
 const skillText=g("Skills",10);if(skillText)txt.skillDetail=skillText.slice(0,1400);
 const spellish=lines.findIndex(x=>/(?:Spell-Like Abilities|Spells Prepared|Spells Known)\s*\(/i.test(x));
 if(spellish>=0){const out=[];for(let i=spellish;i<Math.min(lines.length,spellish+25);i++){if(i>spellish&&/^(STATISTICS|SPECIAL ABILITIES|TACTICS|ECOLOGY|DEFENSE|OFFENSE)$/.test(lines[i]))break;out.push(lines[i]);}txt[/Spell-Like Abilities/i.test(lines[spellish])?"spellLikeAbilities":/Spells Known/i.test(lines[spellish])?"spellsKnown":"spellsPrepared"]=out.join(" ").slice(0,2600);}
 txt.acDetail=ac.slice(0,250);txt.hpDetail=hp.slice(0,250);if(fort)txt.saveDetail=fort.slice(0,250);
 const weapons=[...attacks(melee,"melee"),...attacks(ranged,"ranged")],npcSkills=skills(skillText);
 if(h===null)flags.push("HP missing");
 if(stats.ac===undefined)flags.push("AC missing");
 if(stats.xp===undefined&&category!=="companions")flags.push("XP missing");
 if(stats.cr===undefined&&category!=="companions")flags.push("CR missing or unranked");
 if((melee||ranged)&&!weapons.length)flags.push("Attacks require review");
 if(!npcSkills.length&&skillText)flags.push("Skills require review");
 if(/SPECIAL ABILITIES/.test(raw))flags.push("Special ability rules require source review");
 const activeAbilities=[];
 const abl=raw.split("SPECIAL ABILITIES").at(-1).split(/\n/).map(s=>s.trim()).filter(Boolean);
 if(raw.includes("SPECIAL ABILITIES"))for(const ln of abl.slice(0,28)){
  const m=/^([A-Z][A-Za-z0-9’'() -]{3,70}?)\s+\((Ex|Su|Sp)(?:[^)]*)\)\s+/.exec(ln);
  if(m&&!activeAbilities.some(a=>a.name===m[1]))activeAbilities.push({name:m[1].slice(0,90),ability_kind:m[2].toLowerCase(),desc:"See source PDF p. "+page+" for the full ability rules; requires GM verification."});
 }
 txt.importNotes="Automatically extracted from PDF; verify against printed page before live use. "+(flags.length?"Review: "+flags.join("; "):"Core statistics captured.");
 const first=lines.find(l=>/^(?:Female|Male|Variant|Advanced|Young|Elder|Half-|Dwarf|Elf|Human|Boggard|Troll|Gnome|Undead|Animal)/i.test(l));if(first)txt.raceClassLevels=first.slice(0,180);
 return {name,slug:name.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""),chapter:category,printedPage:page-1,pdfPage:page,
  source:"Pathfinder Kingmaker Bestiary (First Edition)",hp:h,stats,text:txt,weapons,npcSkills,activeAbilities,
  verified:"automated-needs-review",needsRulesReference:true,reviewFlags:flags};
}
function collect(pages,category){
 const stream=chapterText(pages),pattern=/^([A-Z][A-Z0-9 ’'()\/,.-]{2,}?)\s+CR\s+(\d+(?:\/\d+)?|—)\s*$/gm,all=[...stream.matchAll(pattern)],result=[];
 for(let i=0;i<all.length;i++){
  const hit=all[i],markers=[...stream.slice(0,hit.index).matchAll(/\[\[PDFPAGE:(\d+)\]\]/g)],page=Number(markers.at(-1)?.[1]);
  if(!page)continue;
  const raw=stream.slice(hit.index+hit[0].length,i+1<all.length?all[i+1].index:stream.length).replace(/\[\[PDFPAGE:\d+\]\]/g,"\n").slice(0,13000);
  result.push(parseRaw(titleCase(hit[1].trim()),hit[2],raw,category,page));
 }
 return result;
}
export function extractKingmakerChapter(pages,category){return collect(pages,category);}
